def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = int(result.get("credit_limit", 0) or 0)

    # Network referral rule: self_employed with requested_limit above 6000
    # must go to manual review instead of being issued (declines stay declines).
    def is_manual_review_referral():
        if app.get("employment") != "self_employed":
            return False
        try:
            rl = float(app.get("requested_limit"))
        except (TypeError, ValueError):
            return False
        return rl > 6000

    if outcome == "approved":
        if is_manual_review_referral():
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    else:
        # declined
        return {"action": "decline", "limit": 0}
